\label{I_II_II} Let $I_\alpha$ be the Riesz kernel, $0<\alpha<1$, $p\in(1,\infty)$ and $R>0$. Then, denoting by $\sigma_{d-1}$ the surface area of the unit sphere in $\mathbb{R}^d$, we have:
		\begin{enumerate}
			\item[(i)] $\|I_\alpha\|_{L^1(B(0,R))}=\sigma_{d-1}\frac{\gamma_{d,\alpha}}{\alpha}R^\alpha$;		
			\item[(ii)] If $\alpha p<d$ then $\|I_\alpha\|_{L^{p'}(\mathbb{R}^d\setminus B(0,R))}=\gamma_{d,\alpha}\Big(\sigma_{d-1}\frac{p-1}{d-\alpha p}\Big)^{\frac{1}{p'}}R^\frac{\alpha p-d}{p}$.
		\end{enumerate}
		
		As a consequence $\displaystyle\lim_{\alpha\rightarrow 0}\|I_\alpha\|_{L^1(B(0,R))}=1$ and $\displaystyle\lim_{\alpha\rightarrow 0}\|I_\alpha\|_{L^{p'}(\mathbb{R}^d\setminus B(0,R))}=0$.

We start by noticing that, if $b\neq d$, $0\leq R_1\leq R_2<+\infty$, then
		\begin{equation*}
			\int_{B(0,R_2)\setminus B(0,R_1)}\frac{1}{|x|^b}dx  =  \sigma_{d-1}\int_{R_1}^{R_2} r^{d-1-b}dr = \sigma_{d-1}\bigg[\frac{R_2^{d-b}}{d-b}-\frac{R_1^{d-b}}{d-b}\bigg].
		\end{equation*}
		Considering first $b=d-\alpha$, $R_2=R$ and $R_1=0$ we obtain (i). Then choosing $b=(d-a)\frac{p}{p-1}$, $R_1=R$ we obtain (ii) by letting $R_2\rightarrow\infty$ and noticing that $a p<d$ or equivalently $d-b<0$.
		
		Since
		\begin{equation*}
			\lim_{\alpha\rightarrow0}	\frac{\gamma_{d,\alpha}}{\alpha}=\lim_{\alpha\longrightarrow0}\frac{\Gamma(\frac{d-\alpha}2)}{\pi^\frac{d}22^{\alpha+1}\frac{a}{2}\Gamma(\frac{\alpha}{2})}=\lim_{\alpha\rightarrow0}\frac{\Gamma(\frac{d-\alpha}2)}{\pi^\frac{d}22^{\alpha+1}\Gamma(\frac{\alpha}{2}+1)}=\frac{\Gamma(\frac{d}2)}{2\pi^\frac{d}2}=\frac{1}{\sigma_{d-1}},
		\end{equation*}
		the conclusions follows.

\label{ialphag} If $g\in L^p(\mathbb{R}^d)\cap L^\infty(\mathbb{R}^d)\cap C(\mathbb{R}^d)$, for $p>1$, is uniformly continuous in $\mathbb{R}^d$, then
		\begin{equation*}
			\lim_{\alpha\rightarrow 0}\|I_\alpha * g-g\|_{L^\infty(\mathbb{R}^d)}=0.
		\end{equation*}

Let $\varepsilon>0$ and $0<\delta<1$ be such that
		\begin{equation*}
			|z-x|\leq \delta\ \Rightarrow\ |g(z)-g(x)|\leq \varepsilon,\quad 	\forall x,z\in\mathbb{R}^d.
		\end{equation*}
		
		Using Lemma \ref{I_II_II} consider $\alpha_0$ such that, for $0<\alpha<\alpha_0$,
		\begin{equation*}
			\big|\|I_\alpha\|_{L^1(B(0,\delta))}-1\big|\leq \varepsilon, \quad 
			\|I_\alpha\|_{L^{p'}(\mathbb{R}^d\setminus B(0,\delta))}\leq \varepsilon.
		\end{equation*}
		Then, for all $x\in\mathbb{R}^d$,
		\begin{align*}
			(I_\alpha * g)(x)-g(x)=&
			\int_{B(0,\delta)}I_\alpha (y) g(x-y)\,dy+\int_{\mathbb{R}^d\setminus B(0,\delta)}I_\alpha (y) g(x-y)\,dy -g(x)\\
			=&
			\int_{B(0,\delta)}I_\alpha (y)( g(x-y)-g(x))\,dy+
			g(x)\Big(\int_{B(0,\delta)}I_\alpha (y) \,dy-1\Big)\\ &+
			\int_{\mathbb{R}^d\setminus B(0,\delta)}I_\alpha (y) g(x-y)\,dy.
		\end{align*}
		Hence
		\begin{align*}
			|(I_\alpha * g)(x)-g(x)|\leq&
			\varepsilon \|I_\alpha\|_{L^1(B(0,\delta))}+\|g\|_{L^\infty(\mathbb{R}^d)}\big(\|I_\alpha\|_{L^1(B(0,\delta))}-1\big)\\
			&\hspace{3mm}+\|I_\alpha\|_{L^{p'}(\mathbb{R}^d\setminus B(0,\delta))}\|g\|_{L^p(\mathbb{R}^d)}\\
			\leq & \varepsilon^2+\varepsilon\big(\|g\|_{L^\infty(\mathbb{R}^d)}+\|g\|_{L^p(\mathbb{R}^d)}\big)
		\end{align*}
		and the conclusion follows.

\label{2.3}
		For $w\in C^1_c(\mathbb{R}^d)$ we have 
		\begin{equation}\label{Dswdw}
			D^sw\underset{s\rightarrow1}{\longrightarrow}Dw\quad \text{in $\boldsymbol L^\infty(\mathbb{R}^d)$.}
		\end{equation}

\label{dsigma_infty} For $u\in C^1_c(\Omega)$, from \eqref{dsigma2} we easily obtain 
		\begin{equation*}
			|D^s u(x)|\leq \frac{\mu_s }{d(x,\Omega)^{d+s}}\|u\|_{L^1(\Omega)}, \quad \forall x\in\mathbb{R}^d\setminus \overline{\Omega},
		\end{equation*}
		and, consequently, for all $R>0$ 
		\begin{equation*}
			\lim_{s\rightarrow 1}\|D^s u\|_{L^\infty(\mathbb{R}^d\setminus\Omega_R)}=0.
		\end{equation*}

Let $\Omega\subset \mathbb{R}^d$ be a bounded open set. Then there exists a constant $C_0=C_0(\Omega,d)>0$ such that,
		for all $0<s<1$ and $1\leq p\leq \infty$,
		\begin{equation}\label{PoincareSobolevBellido}
			\|u\|_{L^p(\Omega)}\le \tfrac{C_0}{s}\|D^s u\|_{\boldsymbol L^p(\mathbb{R}^d)},\quad \forall u\in \Lambda^{s,p}_0(\Omega).
		\end{equation}

\label{OmegaR} Let $\Omega\subset\mathbb{R}^d$ be a bounded open set,  $p\in[1,\infty)$ and $0<s<1$. Then  there exists a positive constant $C=\big(1+\frac{1}{(p-1)d+ps}\big)C(d,\Omega)$, such that, for $R\geq 1$, 
		\begin{equation}\label{desigualdadeomegaR}
			\int_{\mathbb{R}^d\setminus \Omega_R}|D^s u(x)|^pdx\leq \frac{\mu_s^pC}{R^{(p-1)d+ps}} \|u\|_{L^1(\Omega)}^p, \quad \forall u\in\Lambda_0^{s,p}(\Omega).	
		\end{equation}
		
		As a consequence, the following inclusions hold
		\begin{equation}\label{Omegapq}
			\Lambda_0^{s,q}(\Omega)\subseteq \Lambda_0^{s,p}(\Omega),\quad 1\leq p< q<\infty,
		\end{equation}
		and are continuous, since there exists $C_{p,q}>0$ such that
		\begin{equation}\label{PoincareSobolevLambda}
			\|D^s u\|_{\boldsymbol L^p(\mathbb{R}^d)}\leq C_{p,q} \|D^s u\|_{\boldsymbol L^q(\mathbb{R}^d)},\quad u\in \Lambda_0^{s,q}(\Omega).
		\end{equation}
		
		In addition, $C_{1,q}=\frac{E}{s}$, where $E$ is independent of $s$, and $C_{p,q}$ is independent of $s$, if $p>1$.

\label{inftyp}
		There exists a constant $C_{p,\infty}>0$, which is independent of $s\in [\sigma,1)$ for each $\sigma>0$, such that 
		\eqref{PoincareSobolevLambda} holds for $q=\infty$.  In particular the inclusion 
		\begin{equation*}
			\Lambda^{s,\infty}_0(\Omega)\subset \Lambda^{s,p}_0(\Omega)    
		\end{equation*}  
		is continuous for all $p\geq 1$, and $\Lambda^{s,\infty}_0(\Omega)$ is a Banach space.

From Theorem \ref{OmegaR}, for $R\geq 1$  there exists $C>0$ independent of $R$, such that for all $u\in \Lambda_0^{s,\infty}(\Omega)$,
		\begin{align*}
			\int_{\mathbb{R}^d}|D^s u(x)|^pdx &\leq\int_{\Omega_R}|D^s u(x)|^pdx+\frac{C\mu_s^p}{R^{(p-1)d+ps}} \|u\|_{L^1(\Omega)}^p\\
			&\leq |\Omega_R|\|D^s u\|_{\boldsymbol L^\infty(\mathbb{R}^d)}^p+\frac{C\mu_s^p|\Omega|^{p-1}}{R^{(p-1)d+ps}} \|u\|_{L^p(\Omega)}^p\\
			&\leq |\Omega_R|\|D^s u\|_{\boldsymbol L^\infty(\mathbb{R}^d)}^p+\frac{C_0^p}{s^p}\frac{C\mu_s^p|\Omega|^{p-1}}{R^{(p-1)d+ps}} \|D^su\|_{L^p(\mathbb{R}^n)}^p
		\end{align*}
		by \eqref{PoincareSobolevBellido}.   
		Choosing 
		\begin{equation*}
			R=\max\left\{1,\left(\frac{2C_0^pC\mu_s^p|\Omega|^{p-1}}{s^p}\right)^{\frac{1}{(p-1)d+ps}}\right\}
		\end{equation*}
		we obtain 
		\begin{equation*}
			\|D^su\|_{L^p(\Omega)}\leq 2^{\frac{1}{p}} |\Omega_R|^{\frac{1}{p}} \|D^s u\|_{\boldsymbol L^\infty(\mathbb{R}^d)},
		\end{equation*} 
		which yields the continuity of the embedding $\Lambda^{s,\infty}_0(\Omega)\subset \Lambda^{s,p}_0(\Omega)$.	
		
		Finally,  since a Cauchy sequence $(u_n)$ in $\Lambda^{s,\infty}_0(\Omega)$ is also, for all $1<p<\infty$, a Cauchy sequence in the nested Banach spaces $\Lambda^{s,p}_0(\Omega)$, its common limit $u\in{\bigcap_{1<p<\infty}\Lambda^{s,p}_0(\Omega)}$. As $D^s u_n$ are uniformly bounded, then $D^s u$ is bounded, and therefore $u\in\Lambda^{s,\infty}_0(\Omega)$.

\label{bellido}
		The inclusion \eqref{Omegapq} was also obtained independently in \cite[Corollary 2.4.1]{Campos2021}, as a consequence of an interesting variant of the Poincar\'e inequality, see \cite[Theorem 2.4.3]{Campos2021}, for some constant $C_1=C_1(\Omega,\Omega_1,d)>0$,
		\begin{equation*}\|u\|_{L^p(\Omega)}\leq \tfrac{C_1}{s}\|D^su\|_{\boldsymbol L^p(\Omega_1)},\quad \forall u\in \Lambda_0^{s,p}(\Omega),
		\end{equation*}
		for an open set $\Omega_1\supset B(0,2R)\supset \Omega$, with $R>1$, $1<p<\infty$ and $0<s<1$.

\label{2.10} We note that, for  $p\in[1,\infty)$ we have the inclusions $ W^{1,p}_0(\Omega)\subset \Lambda^{s,p}_0(\Omega)\subset\Lambda^{\sigma,p}_0(\Omega)$, for $0<\sigma<s<1$. We may conclude that, as  a consequence of \eqref{desigualdadeomegaR},  for $R\geq 1$, as $\displaystyle\lim_{s\rightarrow 1}\mu_s=0$,
		\begin{equation*}
			\lim_{s\rightarrow 1}	\|D^s u\|_{L^p(\mathbb{R}^d\setminus\Omega_R)}=0, \quad\forall u\in W^{1,p}_0(\Omega).
		\end{equation*}

Also from Theorem \ref{OmegaR}, for $R\ge1$ we can take the limit as $p\rightarrow\infty$ in \eqref{desigualdadeomegaR}, to conclude (compare with Remark \ref{dsigma_infty}):
		\begin{equation*}
			\|D^su\|_{\boldsymbol L^\infty(\mathbb{R}^d\setminus\Omega_R)}\le\tfrac{\mu_s}{R^{d+s}}\|u\|_{L^1(\Omega)},\quad\forall u\in\Lambda^{s,\infty}_0(\Omega),\ 0<s<1.
		\end{equation*}

\label{r2.12}
		We denote by $W^{1,\infty}_0(\Omega)$  the space of Lipschitz functions vanishing on the boundary of $\Omega$. Extending a function $u\in W^{1,\infty}_0(\Omega)$ by zero outside $\Omega$ and using definition \eqref{dsigma2}, we have, for each $x\in\mathbb{R}^d$,
		\begin{align*}\left|D^s u(x)\right|&\le\mu_s\int_{\mathbb{R}^d}\frac{|u(x)-u(y)|}{|x-y|^{d+s}}\,dy\\
			&=\mu_s\|Du\|_{\boldsymbol L^\infty(\Omega)}\int_{\{|x-y|\le 1\}}\frac{dy}{|x-y|^{d+s-1}}+\mu_s\, 2\|u\|_{L^\infty(\Omega)}\int_{\{|x-y|>1\}}\frac{dy}{|x-y|^{d+s}}\\
			&\le\mu_s\,C_s\|Du\|_{\boldsymbol L^\infty(\Omega)},
		\end{align*}
		for a finite $C_s>0$, by the Poincar\'e inequality and since both integrals are finite for $s\in(0,1)$. Consequently,
		\begin{equation}\label{1sinfty}
			W^{1,\infty}_0(\Omega)\subset\Lambda^{s,\infty}_0(\Omega),\quad\forall s\in(0,1).
		\end{equation}

Let $0<s<1$, $1<p<\infty$ and $F\in \Lambda^{-s,p'}(\Omega)$. Then there exist functions $f_0\in L^{p'}(\Omega)$ and $f_1,\ldots,f_d\in L^{p'}(\mathbb{R}^d)$ such that 
		\begin{equation}\label{dual}
			[F,v]_{s,p}=\int_\Omega f_0v+\sum_{j=1}^d \int_{\mathbb{R}^d}f_jD^s_jv,\quad \forall v\in \Lambda_0^{s,p}(\Omega).
		\end{equation}

\label{desigHolder} 
		Let $p>1$ and $\lambda\in L^\infty(\mathbb{R}^d)'$ be positive. Then
		\begin{equation*}
			\big|\langle\lambda,\varphi\psi\rangle\big|\le\langle\lambda,|\varphi|^p\rangle^\frac1{p}\langle\lambda,|\psi|^{p'}\rangle^\frac1{p'},\quad\forall \varphi,\psi\in L^\infty(\Omega).
		\end{equation*}

\label{teo3.1} Assume \eqref{matrix}, and suppose that
		\begin{enumerate}
			\item[i)] either assumptions \eqref{g0}, \eqref{assumptions1}, and \eqref{assumptions_s1} hold, 
			\item[ii)] or assumptions \eqref{g*}, \eqref{assumptions2}, and \eqref{assumptions_s2} hold.
		\end{enumerate}
		
		Then, for $0<s\leq 1$, there exists a solution of the $s$-gradient constraint variational inequality
		\begin{equation}\label{iv}
			u\in\mathbb{K}^s_g:\qquad\mathscr L^s(u,v-u)\ge[F,v-u]_s,\quad\forall v\in\mathbb{K}_g^s.
		\end{equation}

\label{klimitado} For $1\leq p\leq \infty$ and $g\in L_{loc}^p(\mathbb{R}^d)$, with $g\geq 0$, the set $\mathbb{K}^s_g$ is bounded in $\Lambda^{s,p}_0(\Omega)$. More precisely, there exists $R=R(p,s)$ such that, for $u\in\mathbb{K}^s_g$,
		\begin{equation}\label{1sobrep}
			\|D^s u\|_{\boldsymbol L^p(\mathbb{R}^d)}\le 2^\frac1p \|g\|_{L^p(\Omega_R)},\ \text{if $p<\infty$}, \quad	\|D^s u\|_{\boldsymbol L^\infty(\mathbb{R}^d)}\leq \|g\|_{L^\infty(\Omega_R)}.
		\end{equation}

(of Theorem \ref{teo3.1})
		This existence result in the  Hilbertian case i) is a consequence of a theorem of H. Br\'ezis (see \cite{{Brezis1968}} or \cite[Theorem 8.1, p. 245]{Lions1969}), since $\mathbb{K}^s_g$ is a nonempty, closed and bounded  convex set of $H^s_0(\Omega)$ and the operator $P:H^s_0(\Omega)\longrightarrow H^{-s}(\Omega)$ defined by
		\begin{equation}\label{p}
			[Pu,v]_s=\mathscr L^s(u,v)-[F,v]_s,\quad u,v\in\mathbb{K}^s_g
		\end{equation}
		is pseudo-monotone in $\mathbb{K}^s_g$, i.e., if $u_n\underset{n}\relbar\joinrel\rightharpoonup u$ in $H^s_0(\Omega)$, for $u_n,u\in\mathbb{K}^s_g$ with $\displaystyle\varlimsup_n[Pu_n,u_n-u]_s\le0$ then
		\begin{equation}\label{pseudo}
			\varliminf_n[Pu_n,u_n-v]_s\ge[Pu,u-v]_s,\quad\forall v\in\mathbb{K}^s_g.
		\end{equation}
		
		Indeed, taking $u_n\underset{n}\relbar\joinrel\rightharpoonup u$ in $H^s_0(\Omega)$, which by compactness of the embedding \eqref{2.19} (for $p=2$ and $1\le q<2^*=\frac{2d}{d-2s}$ if $2s<d$, for all $q\ge1$ if $2s=d$ and for $q=\infty$ if $2s>d$), we may assume also that $u_n\underset{n}\rightarrow u$ in $L^q(\Omega)$. Write $P$ in the form
		\begin{equation*}
			[Pu,w]_s=\int_{\mathbb{R}^d}AD^su\cdot D^sw+[Bu,w]_s
		\end{equation*}
		with
		\begin{equation*}
			[Bu,w]_s=\int_{\mathbb{R}^d}(\boldsymbol du-\boldsymbol f)\cdot D^sw+\int_\Omega(\boldsymbol b\cdot D^su+cu-f_{\#})w.
		\end{equation*}
		It is then clear that the assumptions \eqref{assumptions2} and \eqref{assumptions_s2} imply
		\begin{equation*}
			[Bu_n,u_n-v]_s\underset{n}{\rightarrow}[Bu,u-v]_s,
		\end{equation*}
		as $D^su_n\underset{n}\relbar\joinrel\rightharpoonup D^su$ in $\boldsymbol L^2(\mathbb{R}^d)$, and we have 
		\begin{equation*}
			\int_\Omega(\boldsymbol b+\boldsymbol d)u_n\cdot D^su_n\underset{n}\longrightarrow\int_\Omega(\boldsymbol b+\boldsymbol d)u\cdot D^su\quad \text{ and }\  \int_\Omega cu_n^2\underset{n}\longrightarrow \int_\Omega cu^2.
		\end{equation*}
		
		Hence \eqref{pseudo} follows easily by noting that the assumption \eqref{matrix} implies $\displaystyle\int_{\mathbb{R}^d}A D^s(u_n-u)\cdot D^s(u_n-u)\ge 0$, and hence it suffices to take the limit inferior in
		\begin{equation}\label{liminf}
			\int_{\mathbb{R}^d}AD^su_n\cdot D^s u_n\ge\int_{\mathbb{R}^d}AD^su_n\cdot D^su+\int_{\mathbb{R}^d}AD^su\cdot D^su_n-\int_{\mathbb{R}^d}AD^su\cdot D^su.
		\end{equation}
		
		In the non-Hilbertian case, we start by approximating the data, in the respective spaces,  by smooth functions  with compact support $A_m$, $\boldsymbol b_m$, $\boldsymbol d_m$, $c_m$, $f_{\# m}$ and $\boldsymbol f_m$ and we let $u_m$ be a solution of the variational inequality \eqref{iv} with these data, which exists by the previous case. 
		
		As $(D^su_m)_m$ is bounded in $\boldsymbol L^ \infty(\mathbb{R}^d)$ by Lemma \ref{klimitado}, using the compact embedding \eqref{Morrey}, there exist a $u\in\Lambda^{s,\infty}_0(\Omega)$ and a $G\in\boldsymbol L^ \infty(\mathbb{R}^d)$, such that, for some subsequence, $u_m\underset m\longrightarrow u$ strongly in $L^\infty(\Omega)$  and $D^su_m\underset m\relbar\joinrel\rightharpoonup G$ in $\boldsymbol L^\infty(\mathbb{R}^d)\text{-weak}^*$.  Using the distributional nature of $D^s$, we easily see that $G=D^su$. 	Thus, as $\Lambda^{s,\infty}_0(\Omega)$ is continuously included in $\Lambda^{s,p}_0(\Omega)$, we have $D^su_m\underset{m}{\relbar\joinrel\rightharpoonup} D^su$ in $\boldsymbol L^{p}(\mathbb{R}^d)\text{-weak}$, for any $p<\infty$, in particular for $p=p_1'$ and $p=q_1'$.
		
		Using the above convergences, we immediately have, for any $v\in\mathbb{K}^s_g$,
		\begin{multline*}
			\int_{\mathbb{R}^d}(\boldsymbol d_m u_m-\boldsymbol f_m)\cdot D^s(v-u_m)+\int_\Omega(\boldsymbol b_m\cdot D^su_m+ cu_m-f_{\#}m)(v-u_m)\\
			\underset m\longrightarrow\int_{\mathbb{R}^d}(\boldsymbol du-\boldsymbol f)\cdot D^s(v-u_m)+\int_\Omega(\boldsymbol b\cdot D^su+cu-f_{\#})(v-u_m).
		\end{multline*}
		On the other hand, using the monotonicity of $A_m$, for any $v\in\mathbb{K}^s_g$ we have
		\begin{equation*}
			\int_{\mathbb{R}^d}A_m D^su_m\cdot D^s(v-u_m)\le \int_{\mathbb{R}^d}A_m D^sv\cdot D^s(v-u_m).
		\end{equation*}
		Since
		$\displaystyle\int_{\mathbb{R}^d}A_m D^sv\cdot D^s(v-u_m) \underset m\longrightarrow\int_{\mathbb{R}^d}A D^sv\cdot D^s(v-u)$ then we get that, for any $v\in\mathbb{K}_g^s$,
		\begin{equation*}
			\int_{\mathbb{R}^d}A D^sv\cdot D^s(v-u)+	\int_{\Omega}\boldsymbol d u\cdot D^s(v-u)+\int_\Omega(\boldsymbol b\cdot D^su+cu)(v-u) \geq [ F,v-u].
		\end{equation*}
		Choosing $v=u+t(w-u)\in\mathbb{K}^s_g$,  for $t\in(0,1)$, as test function,  we obtain
		\begin{equation*}
			\mathscr L^s(u,w-u)\ge[F,w-u]_s,\quad\forall w\in\mathbb{K}_g^s,
		\end{equation*}
		after letting $t\longrightarrow 0^+$. Therefore $u$ solves \eqref{iv}.

To obtain the uniqueness to \eqref{iv} it suffices to require the strict positivity of the bilinear form
		\begin{equation*}
			\mathscr L^s(u-\widehat u,u-\widehat u)>0,\quad\forall u,\widehat u\in\mathbb{K}_g^s: u\neq\widehat u,
		\end{equation*}
		which needs stronger assumptions on its coefficients.

\label{rem3.4}
		The constrained problem \eqref{iv} for $u\in\mathbb{K}_g^s$ determines the existence of an element $\Gamma=\Gamma(u)\in H^{-s}(\Omega)$ belonging to the sub-differential of the indicatrix function $I_{\mathbb{K}_g^s}$ of the convex set $\mathbb{K}_g^s$, i.e. $I_{\mathbb{K}_g^s}(v)=0$ if $v\in\mathbb{K}_g^s$, $I_{\mathbb{K}_g^s}(v)=+\infty$ if $v\in H^s_0(\Omega)\setminus\mathbb{K}_g^s$, (see \cite[p.203]{Lions1969}), which is given by
		\begin{equation*}
			\Gamma\equiv F-\mathscr L^su\in\partial I_{\mathbb{K}_g^s}\quad\text{ in } H^s_0(\Omega),
		\end{equation*}
		where $\mathscr L^s:\mathbb{K}_g^s\longrightarrow H^{-s}(\Omega)$ is the linear operator defined by the bilinear form as in \eqref{bilinear}. A main question is to relate $\Gamma$ to the solution $u$, for instance trough the existence of a Lagrange multiplier $\lambda$ such that $\Gamma=\lambda D^su$. This has been shown only in very special cases with the classical gradient ($s=1$) (see \cite{Brezis72} and \cite{RodriguesSantos2019_0}, for more references).

\label{teo3.5}
		Let $A\in L^\infty(\mathbb{R}^d)^{d^2}$, $\boldsymbol b,\boldsymbol d\in\boldsymbol L^{\frac{d}s}(\Omega)$, $c\in L^\frac{d}{2s}(\Omega)$ satisfy \eqref{Aelliptic} and \eqref{coercive} for $2s<d$, and $g\in L^2_{loc}(\Omega)$. Then, for any $f_{\#}$ and $\boldsymbol f$ satisfying \eqref{assumptions_s1}, there exists a unique solution to \eqref{iv}. If $\widehat u$ denotes the solution to \eqref{iv} for $\widehat f_{\#}$ and $\widehat{\boldsymbol f}$, we have
		\begin{equation}\label{estimate}
			\|u-\widehat u\|_{H^s_0(\Omega)}\le\tfrac{C_*}\delta\|f_{\#}-\widehat f_{\#}\|_{L^{2^\#}(\Omega)}+\tfrac1\delta\|\boldsymbol f-\widehat{\boldsymbol f}\|_{\boldsymbol L^2(\mathbb{R}^d)}.
		\end{equation}

Using H\"older and Sobolev inequalities, we have that, for $v\in H^s_0(\Omega)$,
		\begin{equation*}
			\Big|\int_\Omega(\boldsymbol b+\boldsymbol d)vD^sv\Big|
			\le\|\boldsymbol b+\boldsymbol d\|_{\boldsymbol L^{\frac{d}{s}}(\Omega)}\|v\|_{L^{2^*}(\Omega)}
			\|D^sv\|_{\boldsymbol L^2(\mathbb{R}^d)}
			\le C_*\|\boldsymbol b+\boldsymbol d\|_{\boldsymbol L^\frac{d}s(\Omega)}\|D^sv\|^2_{\boldsymbol L^2(\mathbb{R}^d)},
		\end{equation*}
		and
		\begin{equation*}
			-\int_\Omega cv^2\le\int_\Omega c^-v^2\le C_*^2\|c^-\|_{L^\frac{d}{2s}(\Omega)}\|D^sv\|^2_{\boldsymbol L^2(\mathbb{R}^d)}.
		\end{equation*}
		
		Therefore, using \eqref{Aelliptic} and \eqref{coercive}, we obtain
		\begin{equation}\label{3.21}
			\begin{aligned}
				\mathscr L^s(v,v)&=\int_{\mathbb{R}^d}AD^sv\cdot D^sv+\int_\Omega(\boldsymbol b+\boldsymbol d)v\cdot D^sv+\int_\Omega cv^2\\
				&\ge a_*\int_{\mathbb{R}^d}|D^sv|^2-\Big(C_*\|\boldsymbol b+\boldsymbol d\|_{\boldsymbol L^{\frac{d}{s}}(\Omega)}+C_*^2\|c^-\|_{L^\frac{d}{2s}(\Omega)}\Big)\|D^sv\|^2_{\boldsymbol L^2(\mathbb{R}^d)}\\
				&=\delta\|D^sv\|^2_{\boldsymbol L^2(\mathbb{R}^d)}=\delta\|v\|^2_{H^s_0(\Omega)}.
			\end{aligned}
		\end{equation}
		As $L^{2^*}(\Omega)=L^{2^{\#}}(\Omega)'$, \eqref{assumptions_s1} implies that $F\in H^{-s}(\Omega)$, with $\|F\|_{H^{-s}(\Omega)}\le C_*\|f_{\#}\|_{L^{2^{\#}}(\Omega)}+\|\boldsymbol f\|_{\boldsymbol L^2(\mathbb{R}^d)}$ and Stampacchia's theorem immediately yields the existence and uniqueness of the solution to \eqref{iv}.
		
		Taking $v=\widehat u$ in \eqref{iv} for $u$ and $v=u$ in \eqref{iv} for $\widehat u$, and using \eqref{3.21}, we obtain
