			\pmb{\langle} \boldsymbol\Psi,D^sv\pmb{\rangle} =[F,v]-\mathscr{L}^s(u,v),\quad \forall v\in \Lambda_0^{s,\infty}(\Omega),
		\end{equation} 
		and, since $\widehat{k}_{\varepsilon}\geq 0$ implies $\lambda\geq 0$, it remains to show that $\boldsymbol\Psi=\lambda D^su$ and $\lambda|D^su|=\lambda g$.
		
		Taking $v=u_\varepsilon$ in \eqref{prob_ap} and using \eqref{4.38} and the semicontinuity \eqref{4.21} for $u_\varepsilon\underset{\varepsilon}{\relbar\joinrel\rightharpoonup}u$ in $\Lambda^{s,r}_0(\Omega)$, we easily obtain 
		\begin{equation*}
			\varlimsup_{\varepsilon\rightarrow 0}\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}|D^su_\varepsilon|^2\leq \pmb{\langle}\boldsymbol\Psi,D^su\pmb{\rangle}.
		\end{equation*}
		
		Comparing the inequality
		\begin{align}	\label{4.39}
			\begin{aligned}
				0 & \leq 	\varlimsup_{\varepsilon\rightarrow 0}\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}|D^s(u_\varepsilon-u)|^2\\
				& =
				\varlimsup_{\varepsilon\rightarrow 0}\bigg(\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}|D^su_\varepsilon|^2-2\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon} D^su_\varepsilon\cdot D^su+\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}|D^su|^2\bigg)	\\
				& \leq \pmb{\langle}\boldsymbol\Psi,D^su\pmb{\rangle}-2 \lim_{\varepsilon\rightarrow 0}\pmb{\langle}\widehat{k}_{\varepsilon} D^su_\varepsilon,D^su\pmb{\rangle}+\lim_{\varepsilon\rightarrow 0}\langle \widehat{k}_{\varepsilon},|D^su|^2\rangle\\
				& \leq \langle \lambda,|D^su|^2\rangle-\pmb{\langle}\boldsymbol\Psi,D^su\pmb{\rangle},
			\end{aligned}
		\end{align}
		with (recall that $\widehat{k}_{\varepsilon} g^2\leq \widehat{k}_{\varepsilon}|D^su_\varepsilon|^2$ by definition of $\widehat{k}_{\varepsilon}$)	
		\begin{equation*}
			\langle\lambda,|D^su|^2\rangle\leq \langle\lambda,g^2\rangle=
			\lim_{\varepsilon\rightarrow 0}\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}\,g^2	\leq \varlimsup_{\varepsilon\rightarrow 0}\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}|D^su_\varepsilon|^2\leq \pmb{\langle}\boldsymbol\Psi,D^su\pmb{\rangle},
		\end{equation*}
		we conclude that
		\begin{equation*}
			\langle\lambda,|D^su|^2\rangle= \langle\lambda,g^2\rangle=
			\varlimsup_{\varepsilon\rightarrow 0}\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}|D^su_\varepsilon|^2= \pmb{\langle}\boldsymbol\Psi,D^su\pmb{\rangle}
		\end{equation*}
		and, afterwards from \eqref{4.39}, also
		\begin{equation*}
			\varlimsup_{\varepsilon\rightarrow 0}\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}|D^s(u_\varepsilon-u)|^2=0.
		\end{equation*}
		
		Then $\boldsymbol\Psi=\lambda D^su$ since, for an arbitrary $\boldsymbol\xi\in\boldsymbol L^\infty(\mathbb{R}^d)$,
		\begin{align*}
			|\pmb{\langle}\boldsymbol\Psi-\lambda D^su,\boldsymbol\xi\pmb{\rangle}| & =	\lim_{\varepsilon\rightarrow 0}\bigg|\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon} D^s(u_\varepsilon-u)\cdot\boldsymbol\xi\bigg|\\
			& \leq 
			\varlimsup_{\varepsilon\rightarrow 0}\bigg(\int_{\mathbb{R}^d}\widehat{k}_{\varepsilon}|D^s(u_\varepsilon-u)|^2\bigg)^\frac12\|\widehat{k}_{\varepsilon}\|_{L^1(\mathbb{R}^d)}^\frac12\|\xi\|_{\boldsymbol L^\infty(\mathbb{R}^d)}=0.
		\end{align*}
		
		From \eqref{4.33} it follows $\langle\lambda,|D^su|^2-g^2\rangle=0$ and we conclude, as in \eqref{4.26}, that  
		$$\lambda(|D^su|-g)=0\quad\text{in }L^\infty(\mathbb{R}^d)'.$$
		
		The general case follows by Theorem \ref{teo4.2}, by approximating with solutions of \ref{mlxa}, \ref{mlxb} with data $A_\nu$, $\boldsymbol b_\nu$, $\boldsymbol d_\nu$, $c$, $f_\#$, $\boldsymbol f_\nu$ and $g$ satisfying \eqref{matrix}, \eqref{dados_regulares} and \eqref{g_*} and converging strongly in $L^{p_1}$, $L^1$ and $L^{q_1}$,  for instance by using  $\boldsymbol f_\nu=\sup(-\frac{1}{\nu},\inf(\frac{1}{\nu},\boldsymbol f))\chi_{B(0,\frac{1}{\nu})}$, where $\chi_{B(0,\frac{1}{\nu})}$ denotes the characteristic function of $B(0,\frac{1}{\nu})$.
		
		Finally, since $u\in\mathbb{K}^s_g$, given $v\in\mathbb{K}^s_g$, taking $v-u$ as test function in \eqref{mla} and noting that
		\begin{align*}
			\pmb{\langle}\lambda D^su,D^s(v-u)\pmb{\rangle}&=\langle\lambda,D^su\cdot D^s(v-u)\rangle=\langle\lambda, D^su\cdot D^sv-|D^su|^2\rangle\\
			& \leq 	\langle\lambda,|D^s u|(|D^sv|-|D^su|)\rangle	\leq 	\langle\lambda,|D^s u|(g-|D^su|)\rangle\\
			&=\langle\lambda(g-|D^su|),|D^su|\rangle=0,
		\end{align*}
		it is clear that $u$ solves the variational inequality \eqref{iv}, which concludes the proof of Theorem \ref{teo4.1}.

\label{local_local_4}
		As in Section 3, we may assume in Theorems \ref{teo4.1} and \ref{teo4.2} that $g$ and $g_\nu$ satisfy \eqref{gweak} instead 
		\eqref{g_*}, with uniform limit in $\nu$.

\label{teo5.1}
		For any  $0<\sigma<1$, let $(u_s,\lambda_s)\in\Lambda^{s,\infty}_0(\Omega)\times L^\infty(\mathbb{R}^d)'$ solve {\em \ref{5.1.s}-\ref{5.2.s}} for any $s$, $0<\sigma<s<1$, under the assumptions \eqref{matrix}, \eqref{assumptions2}, \eqref{assumptions_s2} and \eqref{5.3}, \eqref{5.4}. Then, there is a generalised sequence denoted by $s\rightarrow 1$, such that, for any $0<\alpha<1 $,
		\begin{align*}
			&	u_s\underset{s}\rightarrow u\ \text{ in } \ \Lambda^{\sigma,p}_0(\Omega)\cap C^{0,\alpha}(\overline{\Omega}),\\
			&	D^su_s\underset{s}\relbar\joinrel\rightharpoonup Du\ \text{ in } \ \boldsymbol L^\infty(\mathbb{R}^d)\text{-weak}^*,\\
			&		(\lambda_s)_\Omega\underset{s}\relbar\joinrel\rightharpoonup \lambda \text{ in } \  L^\infty(\Omega)'\text{-weak}^*,
		\end{align*}
		where $(u,\lambda)\in W^{1,\infty}_0(\Omega)\cap L^\infty(\Omega)'$ is a solution to the local problem {\em {\renewcommand1{1}\ref{5.1.s}}-{\renewcommand1{1}\ref{5.2.s}}}, in $\Omega$.

We adapt the steps of the proof of Theorem \ref{teo4.2}: i) {\em a priori} estimates with respect to $s$; ii) existence of limits of generalised sequences, by compactness, and iii) characterization of those limits as solutions of the local
		problem  {\renewcommand1{1}\ref{5.1.s}}- {\renewcommand1{1}\ref{5.2.s}}.		 	
		For $0<\sigma<s<1$, using the Poincar\'e inequality \eqref{PoincareSobolev}, we have $\frac{\sigma}{C_0}\|u_s\|_{L^\infty(\Omega)}\leq \|D^su_s\|_{\boldsymbol L^\infty(\mathbb{R}^d)}$. Then by the assumption \eqref{5.3} we obtain for any $u_s\in\mathbb{K}^s_{g_s}$ solution of \ref{5.1.s}-\ref{5.2.s}, we get that
		\begin{align}
			\begin{aligned}\label{5.9}
				&  C^{-1}_{p,\infty}\|D^su_s\|_{\boldsymbol L^p(\mathbb{R}^d)}\leq \|D^su_s\|_{\boldsymbol L^\infty(\mathbb{R}^d)}\leq g^*,\ 1\leq p<\infty,\\
				& \|u_s\|_{   C^{0,\beta}(\overline{\Omega})}\leq C_\beta,\ 
				\text{for any $\beta$, $0<\beta<s<1$}, 
			\end{aligned}
		\end{align}
		where the constant $C_\beta$ is independent of $s$.
		
		Letting
		$ \boldsymbol\Psi_s=\lambda_s D^s u_s$, arguing exactly as in \eqref{4.11}-\eqref{4.12} and \eqref{4.13}, by replacing the label $\nu$ by $s$, we obtain that
		\begin{align*}
			\|\lambda_s\|_{L^\infty(\mathbb{R}^d)}'\leq \tfrac{C_1}{g_*^2} \quad\text{and}\quad 
			\|\boldsymbol\Psi_s\|_{\boldsymbol L^\infty(\mathbb{R}^d)}'&\leq \tfrac{C_1 g^*}{g_*^2},
		\end{align*}
		where $C_1>0$ is a constant independent of $s$, $\sigma<s<1$
		
		Therefore, by compactness, in particular, by \eqref{5.9} and \eqref{camposembedding}, there are $u\in C^{0,\alpha}(\overline{\Omega})\cap\Lambda^{\sigma,p}(\Omega)$, for $0<\alpha<\beta$, $0<\sigma<1$ and $1<p<\infty$, $\boldsymbol\chi\in\boldsymbol L^\infty(\mathbb{R}^d)$, $\widetilde{\lambda}
		\in L^\infty(\mathbb{R}^d)'$, $\boldsymbol\Psi\in\boldsymbol L^\infty(\mathbb{R}^d)'$ and a generalised sequence $s\rightarrow 1$, such that
		\begin{align*}
			&	u_s\underset{s}\longrightarrow u\ \text{ in } \ \Lambda^{\sigma,p}_0(\Omega)\cap C^{0,\alpha}(\overline{\Omega}),\\
			&	D^su_s\underset{s}\relbar\joinrel\rightharpoonup \boldsymbol\chi\ \text{ in } \ \boldsymbol L^\infty(\mathbb{R}^d)\text{-weak}^*,\\
			&	(\lambda_s)_\Omega\underset{s}\relbar\joinrel\rightharpoonup \lambda \text{ in } \  L^\infty(\Omega)'\text{-weak}^*,\\
			&	\boldsymbol\Psi_s\underset{s}\relbar\joinrel\rightharpoonup \boldsymbol\Psi\ \text{ in } \ \boldsymbol L^\infty(\mathbb{R}^d)\text{-weak}^*.
		\end{align*}
		
		Letting by $\widetilde{u}$ be the extension of $u$ by zero to $\mathbb{R}^d$, and applying Corollary \ref{2.3} componentwise to an arbitrarily $\boldsymbol\varphi\in C^\infty_c(\mathbb{R}^d)^d$, we have, by \eqref{wDs},
		\begin{equation*}
			\int_{\mathbb{R}^d}\boldsymbol \chi\cdot \boldsymbol\varphi =\lim_s\int_{\mathbb{R}^d}D^su^s\cdot\boldsymbol\varphi=-\lim_s\int_{\mathbb{R}^d}\widetilde{u}^sD^s\cdot \boldsymbol\varphi =-\int_{\mathbb{R}^d}\widetilde{u}D\cdot\boldsymbol\varphi,
		\end{equation*} 
		which means that $\boldsymbol\chi=D\widetilde{u}\in\boldsymbol L^\infty(\mathbb{R}^d)$ and $u\in W^{1,\infty}_0(\Omega)$, and therefore $D\widetilde{u}=\widetilde{Du}$.
		
		Arguing as in \eqref{pertence_convexo} with an arbitrarily measurable subset $w\subset\mathbb{R}^d$ with finite measure and with $\boldsymbol \xi=\frac{Du}{|Du|}\chi_V$, $V=w\cap\{|Du|\neq 0\}$, we obtain
		\begin{equation*}
			\int_w|D\widetilde{u}|=\int_{\mathbb{R}^d}D\widetilde{u}\cdot\boldsymbol\xi=\lim_s \int_{\mathbb{R}^d}D^s\widetilde{u}_s\cdot\boldsymbol\xi\leq \varlimsup_s\int_w|D^su_s|\leq\lim_s\int_wg_s=\int_wg_1
		\end{equation*}
		and so $|Du|\leq g_1$ a.e. in $\Omega$, i.e. $u\in \mathbb{K}_{g_1}$.
		
		Observe that we still have the lower semicontinuity property
		\begin{equation}
			\label{5.18}
			\varliminf_s\mathscr{L}^s(u_s,u_s)\geq \mathscr{L}^1(u,u)
		\end{equation}
		as we easily see by using \eqref{matrix} and taking $\varliminf_s$ in 
		\begin{equation*}
			\int_{\mathbb{R}^d}AD^su_s\cdot D^su_s\geq \int_{\mathbb{R}^d}AD^su_s\cdot D\widetilde{u}+\int_{\mathbb{R}^d}AD\widetilde{u}\cdot D^su_s-\int_{\mathbb{R}^d}AD\widetilde{u}\cdot D\widetilde{u}.
		\end{equation*}
		
		On the other hand, recalling \eqref{1sinfty}, we have $C^\infty_c(\Omega)\subset W^{1,\infty}_0(\Omega)\subset \Lambda^{s,\infty}_0(\Omega)$. Taking the limit $s\rightarrow 1$ in \ref{5.1.s} with $v\in C^\infty_c(\Omega)$ we get 
		\begin{equation}
			\label{5.19}
			\mathscr{L}^1(u,v)+\pmb{\langle} \boldsymbol\Psi_\Omega,Dv\pmb{\rangle}=[F,v]_1.
		\end{equation}
		
		Since for each $v\in W^{1,\infty}_0(\Omega)$ we may take a sequence $v_n\in C^\infty_0(\Omega)$ such that $v_n\underset{n}{\longrightarrow}v$ in $H^1_0(\Omega)$ with $Dv_n\underset{n}{\longrightarrow}Dv$ in $\boldsymbol L^\infty(\Omega)\text{-weak}^*$, the equation \eqref{5.19} also holds for any $v\in W^{1,\infty}_0(\Omega)$, as $\boldsymbol\Psi_\Omega\in\boldsymbol L^\infty(\Omega)'$. So {\renewcommand1{1}\ref{5.1.s}} will follows if we show $\boldsymbol\Psi_\Omega=\lambda Du$, with $\lambda=\widetilde{\lambda}_\Omega$, which can be done exactly as in the proof of \eqref{psilambda}, by replacing the subscript $\nu$ by $s$ in \eqref{4.20} and in \eqref{4.24}.
		
		Similarly, the corresponding limit \eqref{4.25} as $s\rightarrow 1$ implies $\langle\lambda(g^2-|Du|^2) ,1\rangle=0$ and the same argument of \eqref{4.26} yields $\lambda(g-|Du|)=0$ in $L^\infty(\Omega)'$, showing that $(u,\lambda)$ also satisfies {\renewcommand1{1}\ref{5.2.s}}  in $\Omega$.

Under the assumptions of Theorem \ref{teo3.5} it is easy to obtain the estimates, similarly to \eqref{estimate},
		\begin{equation*}
			\|u_s\|_{H^s_0(\Omega)}\leq \tfrac{C_*}{\delta}\|f_*\|_{L^{2^\#}(\Omega)}+\tfrac{1}{\delta}\|\boldsymbol f\|_{\boldsymbol L^2(\mathbb{R}^d)}
		\end{equation*}
		and, denoting $\Gamma^s\in \partial I_{\mathbb{K}^s_{g_s}(u_s)}$, as in Remark \ref{rem3.4}, it is easy to conclude that $\Gamma^s$ is also uniformly bounded in $H^{-s}(\Omega)$, independently of $\sigma<s<1$. This allows us to take subsequences $u_s\underset{s}{\longrightarrow} u$ in $H^\sigma_0(\Omega)$ and $\Gamma^s\underset{s}{\longrightarrow}\Gamma$ in $H^{-\sigma}(\Omega)$, $\forall \sigma <1$, with $u\in H^1_0(\Omega)$, $\Gamma\in H^{-1}(\Omega)$ satisfying the local problem $s=1$.
